// Extract sender + message text from WhatsApp Cloud API payload
const body = $input.first().json.body || $input.first().json;
const entry = body.entry?.[0]?.changes?.[0]?.value;
const msg = entry?.messages?.[0];
if (!msg) return [];
return [{ json: {
  from: msg.from,
  text: msg.text?.body || '',
  messageId: msg.id,
  timestamp: msg.timestamp
}}];
